H2 = "font-family: var(--vm-display); font-weight: var(--vm-display-weight, 800); font-size: 24px; line-height: 1.2; color: #223E6B; margin: 40px 0 12px;"
H2BIG = "font-family: var(--vm-display); font-weight: var(--vm-display-weight, 800); font-size: clamp(26px, 2.6vw, 34px); line-height: 1.15; color: #223E6B; margin: 56px 0 8px; padding-top: 40px; border-top: 1px solid #D9E2F0;"
P = "font-size: 16.5px; line-height: 1.7; color: #333333; margin: 0 0 14px; text-wrap: pretty;"
body = ''
for title, paras in SECTIONS:
    if title == 'Terms and Conditions': body += f'<h2 style="{H2BIG}">Terms and Conditions</h2>\n'; continue
    if title: body += f'<h2 style="{H2}">{title}</h2>\n'
    for para in paras:
        para = para.replace('support@apvetmarketing.com', '<a href="mailto:support@apvetmarketing.com" style="color: #2F5694; font-weight: 700;">support@apvetmarketing.com</a>')
        body += f'<p style="{P}">{para}</p>\n'

TEMPLATE = f'''<section id="top" data-screen-label="Privacy hero" style="max-width: 1140px; margin: 0 auto; padding: 150px 32px 24px; box-sizing: border-box; position: relative;">
  <div aria-hidden="true" style="position: absolute; inset: 0; pointer-events: none; overflow: hidden;"><sc-for list="{{{{ pawsHero }}}}" as="bp" hint-placeholder-count="0"><span style="{{{{ bp.style }}}}"></span></sc-for></div>
  <div style="position: relative; max-width: 760px;">
    <div style="font-family: 'polymath-text', sans-serif; font-size: 13px; font-weight: 700; letter-spacing: 0.18em; text-transform: uppercase; color: #2F5694; margin-bottom: 14px;"><a href="index.html" style="color: #2F5694;" style-hover="color: #223E6B;">Home</a><span style="margin: 0 10px; opacity: 0.5;">/</span><span>Privacy &amp; Terms</span></div>
    <h1 style="font-family: var(--vm-display); font-weight: var(--vm-display-weight, 800); font-size: clamp(38px, 4.6vw, 62px); line-height: 1.04; color: #223E6B; margin: 0 0 14px; text-wrap: balance;">Privacy &amp; Terms of Use</h1>
    <p style="font-family: 'polymath-text', sans-serif; font-size: 14px; font-weight: 700; color: #2F5694; margin: 0;">Last updated: May 15, 2025</p>
  </div>
</section>
<section id="policy" data-screen-label="Policy text" style="max-width: 1140px; margin: 0 auto; padding: 8px 32px 104px; box-sizing: border-box;">
  <div style="max-width: 780px;">
{body}  </div>
</section>

'''
t = src
a = t.find('<section id="top"'); b = t.find('<footer id="contact"')
t = t[:a] + TEMPLATE + t[b:]
t = t.replace('<title>Veterinary Marketing Blog | VeterinaryMarketing.com</title>', '<title>Privacy &amp; Terms of Use | VeterinaryMarketing.com</title>')
t = re.sub(r'<meta name="description" content="[^"]*">', '<meta name="description" content="Website privacy policy and terms of use for VeterinaryMarketing.com (Veterinary Marketing, LLC).">', t, count=1)
t = t.replace("const PAGE = { title: 'Veterinary Marketing Blog | VeterinaryMarketing.com' };", "const PAGE = { title: 'Privacy & Terms of Use | VeterinaryMarketing.com' };")
(ROOT / 'privacy-policy.html').write_text(t)
# re-point every privacy link on-site
n = 0
for p in ROOT.glob('*.html'):
    s = p.read_text(); s2 = s.replace('https://www.veterinarymarketing.com/privacy-policy', 'privacy-policy.html')
    s2 = s2.replace('<a href="privacy-policy.html" target="_blank" rel="noopener"', '<a href="privacy-policy.html"')
    if s2 != s: p.write_text(s2); n += 1
print('privacy-policy.html written; links re-pointed in', n, 'pages')
